declare(strict_types=1);require_once __DIR__.'/config/database.php';require_once __DIR__.'/includes/auth.php';requireRole(4);$s=$pdo->query('SELECT COUNT(*) total,COALESCE(SUM(status_arsip=\'Aktif\'),0) aktif,COALESCE(SUM(status_arsip=\'Permanen\'),0) permanen,COALESCE(SUM(status_arsip=\'Musnah\'),0) musnah FROM arsip');$stats=$s->fetch();$s=$pdo->query('SELECT j.nama_jenis,COUNT(*) jumlah FROM arsip a JOIN jenis_surat j ON j.jenis_surat_id=a.jenis_surat_id GROUP BY j.jenis_surat_id,j.nama_jenis ORDER BY jumlah DESC');$types=$s->fetchAll();?>
