ong><?=(int)$stats['musnah']?></strong></article></section><section class="panel"><h2>Rekap Jenis Surat</h2><div class="table-wrap"><table><thead><tr><th>Jenis Surat</th><th>Jumlah</th></tr></thead><tbody><?php foreach($types as $x):?><tr><td><?=e($x['nama_jenis'])?></td><td><?=(int)$x['jumlah']?></td></tr><?php endforeach;?><?php if(!$types):?><tr><td colspan="2">Belum ada data arsip.</td></tr><?php endif;?></tbody></table></div></section></main></div></body></html>